package com.ptms.config;import org.springframework.context.annotation.Configuration;import org.springframework.web.servlet.config.annotation.*;@Configuration public class WebConfig implements WebMvcConfigurer{private final RoleAuthorizationInterceptor guard;public WebConfig(RoleAuthorizationInterceptor g){guard=g;}public void addInterceptors(InterceptorRegistry r){r.addInterceptor(guard).addPathPatterns("/api/**");}}
